head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gUIsurCd; //update시 팝업에 넘겨주기 위해  필요
scwin.gSelctBasYy; //update시 팝업에 넘겨주기 위해  필요
scwin.gExcnt;
scwin.gRdoCreatLoc_tp = "01"; //등록구분_미사용
scwin.LastJob = "";
scwin.gBelngDepCd; //상위부서코드
scwin.gBelngDepCd = js_belngdepcd;
//20250509

scwin.vScrenID = "ULDSTF37409.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setCode = function() {
    dts_single.DataID = "/ByPass.do?method=ExcellentDisclsCorpS_listEmptyHeader";
    dts_single.Reset();
    dts_single.insertRow();
    dts_Delete.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=EXCELLENT_DISCLS_CORP_LIST";
    dts_Delete.Reset();
    dts_Delete.insertRow();

    // 표창유형
    var url = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=VLUP_AWARD_TP_CD";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
};
scwin.fn_init = function() {
    scwin.fn_setCode();

    // 달력
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10); //현재년도
    var byyyy = parseInt(ToDay.getYear() - 1, 10); //전년도
    var mm = parseInt(ToDay.getMonth(), 10) + 1;
    var str = "";
    //선정기준년도  셋팅
    for (var i = yyyy; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_YYYY.CBData = str;

    //시상년도 셋팅
    var nyyyy = parseInt(ToDay.getYear() + 1, 10); //다음년도

    str = "";
    for (var i = nyyyy; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_AW_YYYY.CBData = str;

    //등록구분 초기화(추후 엑셀 등록 요청시 주석 풀것)
    //setObjectValue(rdo_creatloc_tp, "01");

    txt_SelectBasYy.style.visibility = "hidden";
    params = $c.frame.path("../").params;
    str = "";
    $c.stf.showObj(pnl_valueup, false); //밸류업팀에서 입력하는 부분
    $c.stf.showObj(lbl_2, false);

    //시장구분에 따른 유형설정
    if (js_market == "1") {
        //유가_선정유형
        label_1.setValue("선정유형");
        str = "11^공시우수법인,12^우수위원,13^공시우수법인(코스닥)";
    } else if (js_market == "2") {
        //코스닥_유형
        label_1.setValue("유형");
        str = "21^장기성실공시우수,22^실적예측공시우수,23^IR활동우수,24^종합평가우수,25^우수위원";
    } else {
        if (scwin.gBelngDepCd == "1I00" || scwin.gDepCd == "1I00") {
            //밸류업지원부 
            str = "99^밸류업 우수기업";
            $c.stf.showObj(pnl_valueup, true); //밸류업팀에서 입력하는 부분
            $c.stf.showObj(lbl_2, true);
        } else {
            str = "99^밸류업 우수기업,21^(코)장기성실공시우수,22^(코)실적예측공시우수,23^(코)IR활동우수,24^(코)종합평가우수,25^(코)우수위원,11^(유)공시우수법인,12^(유)우수위원,13^(유)공시우수법인(코스닥)";
        }
    }
    cmb_Excnt.CBData = str;
    if (params == "update") {
        //수정
        btn_Save.src = "../img/btn_Chg.gif";

        //rdo_creatloc_tp.Enable = false;
        txb_isur_cd.setReadOnly(true);
        img_com_srch.style.visibility = "hidden";
        scwin.gUIsurCd = $c.frame.path("../").scwin.gUIsurCd;
        scwin.gSelctBasYy = $c.frame.path("../").scwin.gSelctBasYy;
        gComAbbrv = $c.frame.path("../").gComAbbrv;
        scwin.gExcnt = $c.frame.path("../").scwin.gExcnt;
        var url = "/ByPass.do?method=readExcellentDisclsCorp";
        url += "&ISUR_CD=" + scwin.gUIsurCd;
        url += "&SELCT_BAS_YY=" + scwin.gSelctBasYy;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List.DataID = encodeURI(url);
        dts_List.reset();
    } else {
        //등록
        btn_Delete.style.visibility = "hidden";
        $c.stf.setObjectValue(cmb_YYYY, byyyy);
        $c.stf.setObjectValue(cmb_AW_YYYY, yyyy);
        if (js_market == "1") {
            $c.stf.setObjectValue(cmb_Excnt, "11");
        } else if (js_market == "2") {
            $c.stf.setObjectValue(cmb_Excnt, "21");
        }
    }
    //dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_FileList.insertRow();
};


/**
 *등록 패널 변경
 */
scwin.setDisplayPanal = function(rdo_creatloc_tp) {
    if (scwin.gRdoCreatLoc_tp == "01") {
        //단건
        panel_2.style.visibility = "";
        panel_3.style.visibility = "hidden";
    } else {
        //엑셀
        panel_2.style.visibility = "hidden";
        panel_3.style.visibility = "";
    }
};
scwin.fn_Save = function() {
    var txb_isur_cd_value = $c.stf.getObjectValue(txb_isur_cd);
    var cmb_YYYY_value = $c.stf.getObjectValue(cmb_YYYY);
    var cmb_AW_YYYY_value = $c.stf.getObjectValue(cmb_AW_YYYY);
    var cmb_Excnt_value = $c.stf.getObjectValue(cmb_Excnt);
    var txt_award_prn_nm_value = $c.stf.getObjectValue(txt_award_prn_nm);
    var edt_design_dd_value = $c.stf.getObjectValue(edt_design_dd);
    var txt_remk_value = txt_remk.Text;
    var cmb_Award_value = "";
    var txt_ord_value = "";
    if (cmb_Excnt_value == '99') {
        cmb_Award_value = $c.stf.getObjectValue(cmb_Award);
        txt_ord_value = $c.stf.getObjectValue(txt_ord);
    }
    if (!scwin.fn_DateCheck(cmb_YYYY_value, $c.ut.trim(cmb_AW_YYYY_value))) {
        return;
    }
    if (!scwin.validCheck(params)) {
        return;
    }
    if (params == "update") {
        var res = window.confirm("[변경]하시겠습니까?");
        if (res) {
            dts_single.setCellData(1, "ISUR_CD", txb_isur_cd_value);
            dts_single.setCellData(1, "SELCT_BAS_YY", cmb_YYYY_value);
            dts_single.setCellData(1, "EXCNT_DISCLS_CORP_AWARD_YY", cmb_AW_YYYY_value);
            dts_single.setCellData(1, "EXCNT_DISCLS_CORP_TP_CD", cmb_Excnt_value);
            dts_single.setCellData(1, "REG_ID", js_id);
            dts_single.setCellData(1, "AWARD_PRN_NM", txt_award_prn_nm_value);
            dts_single.setCellData(1, "DESIGN_DD", edt_design_dd_value);
            dts_single.setCellData(1, "REMK", txt_remk_value);
            dts_single.setCellData(1, "VLUP_AWARD_TP_CD", cmb_Award_value);
            dts_single.setCellData(1, "VLUP_EXCNT_CORP_ORD", txt_ord_value);
            scwin.LastJob = "변경 ";
            trs_Save.Action = "/ByPass.do?method=updateExcellentDisclsCorp" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_single)";
            trs_Save.post();
        }
    } else {
        var res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            if (scwin.gRdoCreatLoc_tp == "01") {
                //단건 등록

                //if (trim(cmb_AW_YYYY_value) == "") {
                //	msg = getMessageParam("MSG-A005", "시상년도");
                //	alert(msg);cmb_AW_YYYY.focus();return;
                //}

                dts_single.setCellData(1, "ISUR_CD", txb_isur_cd_value);
                dts_single.setCellData(1, "SELCT_BAS_YY", cmb_YYYY_value);
                dts_single.setCellData(1, "EXCNT_DISCLS_CORP_AWARD_YY", cmb_AW_YYYY_value);
                dts_single.setCellData(1, "EXCNT_DISCLS_CORP_TP_CD", cmb_Excnt_value);
                dts_single.setCellData(1, "REG_ID", js_id);
                dts_single.setCellData(1, "AWARD_PRN_NM", txt_award_prn_nm_value);
                dts_single.setCellData(1, "DESIGN_DD", edt_design_dd_value);
                dts_single.setCellData(1, "REMK", txt_remk_value);
                dts_single.setCellData(1, "VLUP_AWARD_TP_CD", cmb_Award_value);
                dts_single.setCellData(1, "VLUP_EXCNT_CORP_ORD", txt_ord_value);
                scwin.LastJob = "저장";
                trs_Save.Action = "/ByPass.do?method=registerExcellentDisclsCorpS" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
                trs_Save.KeyName = "toinb_dataid4";
                trs_Save.KeyValue = "JSP(I:pInputMaster=dts_single)";
                trs_Save.post();
            } else {
                //엑셀 등록
                var file_nm = $c.stf.getObjectValue(txb_ATTACH_FILE_NM);
                if (file_nm == "") {
                    msg = $c.stf.getMessageParam("MSG-A005", "파일업로드");
                    $c.win.alert(msg);
                    txb_ATTACH_FILE_NM.focus();
                    return;
                }
                scwin.LastJob = "엑셀저장";
                trs_Save.Action = "/ByPass.do?method=registerExcellentDisclsCorpE" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
                trs_Save.KeyName = "toinb_dataid4";
                trs_Save.KeyValue = "JSP(I:pInputMaster=dts_single,I:pFile=dts_FileList)";
                trs_Save.post();
            }
        }
    }
};





/**
 * 신규, 업데이트시 validation 체크 함수
 */
scwin.validCheck = function(params) {
    if (params == "update") {
        //변경시 체크

    } else {
        //신규시 체크
        if ($c.stf.getObjectValue(txb_isur_cd) == "") {
            msg = $c.stf.getMessageParam("MSG-A005", "회사코드(명)");
            $c.win.alert(msg);
            txb_isur_cd.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_YYYY) == "") {
            msg = $c.stf.getMessageParam("MSG-A005", "선정기준년도");
            $c.win.alert(msg);
            cmb_YYYY.focus();
            return false;
        }
    }

    //밸류업 우수기업 일때 수상자는 체크하지 않는다. 20250718
    if ($c.stf.getObjectValue(txt_award_prn_nm) == "") {
        if ($c.stf.getObjectValue(cmb_Excnt) != "99") {
            msg = $c.stf.getMessageParam("MSG-A005", "수상자");
            $c.win.alert(msg);
            txt_award_prn_nm.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txt_ord) != "") {
        if (!$c.ut.isNum($c.stf.getObjectValue(txt_ord))) {
            $c.win.alert("표시순서는 숫자만 입력하십시오");
            txt_ord.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txt_ord).length > 3) {
            $c.win.alert("표시순서는 3자리 이하로 입력하십시오");
            txt_ord.focus();
            return false;
        }
    }
    var taSize = 10;
    var overLenTa = eval($c.stf.getStringSize(txt_award_prn_nm.getValue()) - taSize);
    if (overLenTa > 0) {
        $c.win.alert("[ 수상자 ] 항목의 최대입력은 [ " + taSize + " ] byte 입니다.    \n\n[ " + overLenTa + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        txt_award_prn_nm.focus();
        return false;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_design_dd) == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "지정일자");
        $c.win.alert(msg);
        edt_design_dd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_design_dd).length < 8) {
        $c.win.alert("지정일자를 올바르게 입력하십시오.");
        edt_design_dd.focus();
        return false;
    }
    taSize = 2000;
    //비고_TxtArea일때의 길이체크
    overLenTa = eval($c.stf.getStringSize(txt_remk.Text) - taSize);
    if (overLenTa > 0) {
        $c.win.alert("[ 비고 ] 항목의 최대입력은 [ " + taSize + " ] byte 입니다.    \n\n[ " + overLenTa + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        txt_remk.focus();
        return false;
    }
    return true;
};


//파일선택
scwin.fn_SelectAttach = function() {
    if (file.getValue() == "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
};
scwin.fn_DateCheck = function(vSelct_bas_yy, vExcnt_discls_corp_award_yy) {
    if (vExcnt_discls_corp_award_yy != "") {
        if (Number(vSelct_bas_yy) > Number(vExcnt_discls_corp_award_yy)) {
            $c.win.alert("'시상년도'는 '선정기준년도'이후여야 합니다.");
            $c.stf.setObjectValue(cmb_AW_YYYY, vSelct_bas_yy);
            cmb_AW_YYYY.focus();
            return false;
        }
    }
    return true;
};


//삭제처리
scwin.fn_Delete = function() {
    var res = window.confirm("삭제하시겠습니까?");
    if (res) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Delete.UserStatus(1) = TB_JOB_DELETE;*/
        X = TB_JOB_DELETE;
        dts_Delete.setCellData(1, "SELCT_BAS_YY", scwin.gSelctBasYy);
        dts_Delete.setCellData(1, "ISUR_CD", scwin.gUIsurCd);
        trs_delete.Action = "/ByPass.do?method=deleteExcntDisclsCorp" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_delete.KeyName = "toinb_dataid4";
        trs_delete.KeyValue = "JSP(I:pInput=dts_Delete)";
        trs_delete.Post();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (params != "update") {
            if (window.event.keyCode == 40) {
                //아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert(scwin.LastJob + "에 실패하였습니다.");
    //alert(getObjectValue(txb_com_abbrv) + "은(는) " + getObjectValue(cmb_YYYY) + "년에 등록된 내역이 존재합니다.");

};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.LastJob);
    $c.win.alert(msg);

    //setObjectValue(txb_isur_cd, "");
    //setObjectValue(txb_com_abbrv, "");

    //dts_single.ClearData();
    //dts_FileList.ClearData();	
    //dts_single.AddRow();
    //dts_FileList.AddRow();
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_init();

    //회사정보 로딩
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.setObjectValue(cmb_YYYY, dts_List.getCellData(1, "SELCT_BAS_YY"));
        $c.stf.setObjectValue(cmb_AW_YYYY, dts_List.getCellData(1, "EXCNT_DISCLS_CORP_AWARD_YY"));
        $c.stf.setObjectValue(txb_isur_cd, dts_List.getCellData(1, "ISUR_CD"));
        $c.stf.setObjectValue(cmb_Excnt, dts_List.getCellData(1, "EXCNT_DISCLS_CORP_TP_CD"));
        $c.stf.setObjectValue(txt_award_prn_nm, dts_List.getCellData(1, "AWARD_PRN_NM"));
        $c.stf.setObjectValue(edt_design_dd, dts_List.getCellData(1, "DESIGN_DD"));
        $c.stf.setObjectValue(cmb_Award, dts_List.getCellData(1, "VLUP_AWARD_TP_CD"));
        $c.stf.setObjectValue(txt_ord, dts_List.getCellData(1, "VLUP_EXCNT_CORP_ORD"));
        txt_remk.Text = dts_List.getCellData(1, "REMK");

        //setObjectValue(txt_remk, dts_List.NameString(1, "REMK"));

        //수정을 위한 기존의 선정기준년도 셋팅
        dts_single.setCellData(1, "OLD_SELCT_BAS_YY", dts_List.getCellData(1, "SELCT_BAS_YY"));
        $c.stf.setObjectValue(txb_com_abbrv, gComAbbrv);
    }
};
