scwin.cmb_Excnt_OnSelChange = function() {
    var ExcntVal = $c.stf.getObjectValue(cmb_Excnt);
    if (ExcntVal == '99') {
        //밸류업 우수기업 유형 선택시 
        $c.stf.showObj(pnl_valueup, true);
        $c.stf.showObj(lbl_2, true);
    } else {
        $c.stf.showObj(pnl_valueup, false);
        $c.stf.showObj(lbl_2, false);
    }
};
